/**
 * Workspaces API module
 *
 * Covers all workspace-related API operations:
 *   - CRUD (list, get, create, update, delete)
 *   - Templates
 *   - Lifecycle (start, stop, status, logs)
 *   - Workspace files (list, read, write)
 *
 * Mirrors the backend router defined in:
 *   codx/junior/api/workspaces.py
 *
 * @typedef {import('../model/workspace.js').Workspace}              Workspace
 * @typedef {import('../model/workspace.js').WorkspaceApp}           WorkspaceApp
 * @typedef {import('../model/workspace.js').WorkspaceResources}     WorkspaceResources
 * @typedef {import('../model/workspace.js').WorkspaceStatus}        WorkspaceStatus
 * @typedef {import('../model/workspace.js').WorkspaceStatusResponse} WorkspaceStatusResponse
 * @typedef {import('../model/workspace.js').WorkspaceLogsResponse}  WorkspaceLogsResponse
 * @typedef {import('../model/workspace.js').WorkspaceFileReadResponse} WorkspaceFileReadResponse
 * @typedef {import('../model/workspace.js').WorkspaceFileWriteResponse} WorkspaceFileWriteResponse
 * @typedef {import('../model/workspace.js').WorkspaceDeleteResponse} WorkspaceDeleteResponse
 */

export const workspacesModule = (API) => ({

  // ── CRUD ─────────────────────────────────────────────────────────────────

  /**
   * List all workspaces accessible to the authenticated user.
   * Admins receive all workspaces; regular users only see public ones
   * or those where their username appears in user_ids.
   * @returns {Promise<Workspace[]>}
   */
  list() {
    return API.get('/api/workspaces')
  },

  /**
   * Fetch a single workspace by id.
   * Returns 403 if the authenticated user lacks access.
   * @param {string} workspaceId
   * @returns {Promise<Workspace>}
   */
  get(workspaceId) {
    return API.get(`/api/workspaces/${workspaceId}`)
  },

  /**
   * Create a new workspace (admin only).
   *
   * ``folder_path`` is required and must be unique.
   * ``id`` is always assigned server-side — any supplied value is ignored.
   *
   * @param {Workspace} workspace
   * @returns {Promise<Workspace>}
   */
  create(workspace) {
    return API.post('/api/workspaces', workspace)
  },

  /**
   * Replace workspace metadata (admin only).
   * Send the full Workspace object; files inside the workspace directory
   * are not touched unless reprovision=true.
   *
   * @param {Workspace} workspace
   * @param {boolean}   [reprovision=false] - Re-create workspace directory if missing
   * @returns {Promise<Workspace>}
   */
  update(workspace, reprovision = false) {
    return API.put(`/api/workspaces?reprovision=${reprovision ? 1 : 0}`, workspace)
  },

  /**
   * Delete a workspace (admin only).
   * Stops running containers, removes workspace directory, and purges
   * the record. Irreversible.
   *
   * @param {string} workspaceId
   * @returns {Promise<WorkspaceDeleteResponse>}
   */
  delete(workspaceId) {
    return API.del(`/api/workspaces/${workspaceId}`)
  },

  // ── Templates ─────────────────────────────────────────────────────────────

  templates: {
    /**
     * Return all available workspace starter templates (admin only).
     * Pass template.id as Workspace.template when creating a workspace.
     * @returns {Promise<Object[]>}
     */
    list() {
      return API.get('/api/workspaces/templates')
    },
  },

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  lifecycle: {
    /**
     * Start all services defined in the workspace's docker-compose.yaml
     * (docker compose up -d).
     * Returns updated Workspace with status "running" on success or "error" on failure.
     * Prerequisite: a valid docker-compose.yaml must exist — upload one first via files.write().
     *
     * @param {string} workspaceId
     * @returns {Promise<Workspace>}
     */
    start(workspaceId) {
      return API.post(`/api/workspaces/${workspaceId}/start`, {})
    },

    /**
     * Stop all running containers in the workspace (docker compose stop).
     * Data volumes are preserved.
     *
     * @param {string} workspaceId
     * @returns {Promise<Workspace>}
     */
    stop(workspaceId) {
      return API.post(`/api/workspaces/${workspaceId}/stop`, {})
    },

    /**
     * Return the live container status by querying docker compose ps.
     * Unlike Workspace.status (persisted), this always reflects real Docker state.
     * Possible values: stopped | starting | running | error
     *
     * @param {string} workspaceId
     * @returns {Promise<WorkspaceStatusResponse>}
     */
    status(workspaceId) {
      return API.get(`/api/workspaces/${workspaceId}/status`)
    },

    /**
     * Return the last ``tail`` lines of combined container logs (admin only).
     * Aggregates stdout + stderr from all services (docker compose logs --tail=N).
     *
     * @param {string} workspaceId
     * @param {number} [tail=200] - Number of log lines (1–5000)
     * @returns {Promise<WorkspaceLogsResponse>}
     */
    logs(workspaceId, tail = 200) {
      return API.get(`/api/workspaces/${workspaceId}/logs?tail=${tail}`)
    },
  },

  // ── Workspace files ───────────────────────────────────────────────────────

  files: {
    /**
     * List all files inside the workspace directory (admin only).
     * Returns paths relative to the workspace root,
     * e.g. ["docker-compose.yaml", ".env", "scripts/init.sh"]
     *
     * @param {string} workspaceId
     * @returns {Promise<string[]>}
     */
    list(workspaceId) {
      return API.get(`/api/workspaces/${workspaceId}/files`)
    },

    /**
     * Read a file from the workspace directory (admin only).
     * ``filePath`` must be relative to the workspace root.
     * Path traversal is blocked server-side — escaping the directory returns 400.
     *
     * @param {string} workspaceId
     * @param {string} filePath  - Relative path, e.g. "docker-compose.yaml"
     * @returns {Promise<WorkspaceFileReadResponse>}
     */
    read(workspaceId, filePath) {
      return API.get(`/api/workspaces/${workspaceId}/file?path=${encodeURIComponent(filePath)}`)
    },

    /**
     * Write (create or overwrite) a file in the workspace directory (admin only).
     * Missing parent directories are created automatically.
     * Path traversal is blocked server-side — escaping the workspace root returns 400.
     *
     * @param {string} workspaceId
     * @param {string} filePath  - Relative path to write, e.g. "docker-compose.yaml"
     * @param {string} content   - Full UTF-8 text content
     * @returns {Promise<WorkspaceFileWriteResponse>}
     */
    write(workspaceId, filePath, content) {
      return API.post(
        `/api/workspaces/${workspaceId}/file?path=${encodeURIComponent(filePath)}`,
        { content },
      )
    },
  },
})

import { CodxJuniorConnection } from './connection'
import { SocketManager } from './socket'
import { filesModule } from './modules/files'
import { globalSettingsModule } from './modules/globalSettings'
import { analyticsModule } from './modules/analytics'
import { logsModule } from './modules/logs'
import { viewsModule } from './modules/views'
import { chatsModule } from './modules/chats'
// ADDED: workspaces module
import { workspacesModule } from './modules/workspaces'

/**
 * In-flight request deduplication map.
 * Key: "METHOD:url:serialized_body"
 * Value: Promise
 */
const _inflightRequests = new Map()

/**
 * Static, singleton socket manager shared across all API instances.
 */
let _staticSocketManager = null

/**
 * Build a stable cache key for a request.
 */
function _requestKey(method, url, data) {
  const body = data !== undefined ? JSON.stringify(data) : ''
  return `${method.toUpperCase()}:${url}:${body}`
}

/**
 * Wrap a request factory in deduplication logic.
 * If an identical request is already in-flight, the new caller
 * receives the same Promise (and therefore the same resolved value).
 */
function _dedupedRequest(method, url, data, requestFn) {
  const key = _requestKey(method, url, data)

  if (_inflightRequests.has(key)) {
    return _inflightRequests.get(key)
  }

  const promise = requestFn().finally(() => {
    _inflightRequests.delete(key)
  })

  _inflightRequests.set(key, promise)
  return promise
}

const initializeAPI = ({ project, user } = {}) => {
  const API = {
    sid: "",
    connection: null,
    _user: user,

    get user () {
      return API._user
    },
    set user(user) {
      API._user = user
      API.initConnection()
    },

    _activeProject: project,
    get activeProject() {
      return this._activeProject
    },
    set activeProject(value) {
      this._activeProject = value
      API.initConnection()
    },

    set interceptors(value) {
      Object.assign(this.connection.interceptors, value)
    },

    initConnection() {
      API.connection = new CodxJuniorConnection({
        settings: API.activeProject,
        user: API.user
      })
    },

    // ─── HTTP helpers ────────────────────────────────────────────────────────

    get(url) {
      return _dedupedRequest('GET', API.connection.prepareUrl(url), undefined, () => API.connection.get(url))
    },
    del(url) {
      return _dedupedRequest('DEL', API.connection.prepareUrl(url), undefined, () => API.connection.del(url))
    },
    post(url, data) {
      return _dedupedRequest('POST', API.connection.prepareUrl(url), data, () => API.connection.post(url, data))
    },
    put(url, data) {
      return _dedupedRequest('PUT', API.connection.prepareUrl(url), data, () => API.connection.put(url, data))
    },
    delete(url) {
      return _dedupedRequest('DELETE', API.connection.prepareUrl(url), undefined, () => API.connection.delete(url))
    },

    // ─── Socket management (static/singleton) ────────────────────────────────

    initSocket({ onConnect, onDisconnect, onEvent } = {}) {
      if (_staticSocketManager) {
        _staticSocketManager.disconnect()
      }

      _staticSocketManager = new SocketManager({
        onConnect(socketId) {
          API.sid = socketId
          if (typeof onConnect === 'function') onConnect(socketId)
        },
        onDisconnect() {
          API.sid = ''
          if (typeof onDisconnect === 'function') onDisconnect()
        },
        onEvent(payload) {
          if (typeof onEvent === 'function') onEvent(payload)
        }
      })

      _staticSocketManager.connect()
      return _staticSocketManager
    },

    get socket() {
      return _staticSocketManager
    },

    disconnectSocket() {
      if (_staticSocketManager) {
        _staticSocketManager.disconnect()
        _staticSocketManager = null
      }
    },

    // ─── Domain helpers ──────────────────────────────────────────────────────

    oauth: {
      async getOAuthLoginUrl(provider) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${provider}`)
        return await API.get(`/api/users/oauth-login-url/${provider}?redirect_uri=${redirect_uri}`)
      },
      async oauthLogin({ oauth_provider, code, state }) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${oauth_provider}`)
        const data = await API.post('/api/users/oauth-login', {
          oauth_provider,
          code,
          state,
          redirect_uri
        })
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      }
    },
    users: {
      async list() {
        API.userNetwork = await API.get('/api/users')
        return API.userNetwork
      },
      async login(user) {
        if (!user) {
          try {
            user = API.user = JSON.parse(localStorage.getItem("CODX_USER"))
            API.initConnection()
          } catch {}
          if (!user) return null
        }
        const data = await API.post('/api/users/login', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      },
      async save(user) {
        const data = await API.put('/api/users', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        return data
      },
      async logout() {
        API.user = null
        API.activeProject = {}
        localStorage.removeItem("CODX_USER")
      },
      async refreshInfo() {
        const data = await API.get('/api/users/me/refresh')
        if (data && API.user) {
          API.user = {
            ...API.user,
            token_usage_today: data.token_usage_today,
            token_limits_today: data.token_limits_today,
            token_limit_rules: data.token_limit_rules,
            token_limit_requests: data.token_limit_requests,
          }
        }
        return data
      }
    },
    apps: {
      async list() {
        const apps = await API.get('/api/apps')
        return apps
      },
      async run(appName) {
        const data = await API.get(`/api/apps/run?app=${appName}`)
        return data
      },
      async runScript(script) {
        const data = await API.post('/api/run/script', { script })
        return data
      }
    },
    async project(projectOrId) {
      if (!projectOrId.codx_path) {
        const existingProject = API.allProjects.find(p => p.id === projectOrId || p.project_name === projectOrId)
        if (!existingProject) {
          throw new Error("Invalid projectOrId: " + JSON.stringify(projectOrId))
        }
        projectOrId = existingProject
      }
      if (projectOrId.codx_path === API.settings.codx_path) {
        return API
      }
      return initializeAPI({ ...API, project: projectOrId })
    },
    projects: {
      async list(withMetrics) {
        const { projects, workspaces } = await API.get(`/api/projects?with_metrics=${withMetrics ? 1 : 0}`)
        API.allProjects = projects
        API.workspaces = workspaces
        API.allProjects.forEach(p => {
          const projectPath = p.abs_project_path
          p.parentProject = API.allProjects
            .filter(p => p.abs_project_path != projectPath && projectPath.startsWith(p.abs_project_path))
            .sort((a, b) => a.abs_project_path > b.abs_project_path ? -1 : 1)[0]
        })
        return API.allProjects
      },
      create(projectPath) {
        return API.post('/api/projects?project_path=' + encodeURIComponent(projectPath), {})
      },
      delete() {
        localStorage.setItem("API_SETTINGS", "")
        API.del('/api/projects')
        API.activeProject = null
      },
      async readme() {
        const data = await API.get('/api/projects/readme')
        return data
      },
      async watch(watching) {
        const settings = await API.settings.read()
        settings.watching = watching
        API.settings.save(settings)
      },
      test() {
        return API.get('/api/project/script/test')
      },
      loadIssue(url) {
        return API.get('/api/github/issues/read?issue_url=' + encodeURIComponent(url))
      },
      ai: {
